// Mapuje typ żaluzji (jt) na kolumnę dostępności tasiemki
export function jzTasWidthGroup(jt){
  if(jt==="ba27")return "ba27";
  if(jt==="al35")return "al35";
  if(jt==="al50")return "al50";
  if(jt==="bs50")return "bs50";
  if(jt==="ab50"||jt==="ba50"||jt==="pw50")return "abp50";
  if(jt==="ab35"||jt==="ba35"||jt==="bs35"||jt==="pw35")return "z35";
  if(jt==="ab65"||jt==="ba65"||jt==="bs65")return "z65";
  return null;
}

